dashboard.definition:
{
 "title": "Peer Pivot",
 "description": "Everything a single IP address did across the estate: reach, ports, timing regularity and the processes that talked to it.",
 "visualizations": {
  "hdr": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## Peer pivot — $tk_peer$\nEverything this address did, across the whole estate. Paste an IP above, or arrive here by clicking a peer in another view.",
    "fontSize": "large",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_total": {
   "type": "splunk.singlevalue",
   "title": "Events",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('total') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#dbe0e6"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_blocked": {
   "type": "splunk.singlevalue",
   "title": "Blocked",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#e5484d"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_pct": {
   "type": "splunk.singlevalue",
   "title": "Blocked ratio",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('blocked_pct') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)",
    "unit": "%",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 5,
      "value": "#2fb67c"
     },
     {
      "from": 5,
      "to": 50,
      "value": "#f5a623"
     },
     {
      "from": 50,
      "value": "#e5484d"
     }
    ]
   }
  },
  "kpi_hosts": {
   "type": "splunk.singlevalue",
   "title": "Hosts involved",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "How far this address reached into the estate. More than a handful for an external address deserves attention."
  },
  "kpi_ports": {
   "type": "splunk.singlevalue",
   "title": "Ports touched",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('ports') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#a175ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_mb": {
   "type": "splunk.singlevalue",
   "title": "Volume",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('mb') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "#31c2c9",
    "unit": "MB",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_id": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Identity",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_identity": {
   "type": "splunk.table",
   "title": "",
   "dataSources": {
    "primary": "ds_identity"
   },
   "options": {
    "count": 3,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_timechart": {
   "type": "splunk.area",
   "title": "Activity over time",
   "dataSources": {
    "primary": "ds_timechart"
   },
   "options": {
    "stackMode": "stacked",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#8c9199"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "Events",
    "xAxisTitleText": ""
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_reach": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Reach — click a host to open its 360 view",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_hosts": {
   "type": "splunk.table",
   "title": "Hosts that exchanged traffic with this address",
   "dataSources": {
    "primary": "ds_hosts"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_ports": {
   "type": "splunk.table",
   "title": "Ports and services",
   "dataSources": {
    "primary": "ds_ports"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "hdr_pattern": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Timing and attribution",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_pattern": {
   "type": "splunk.table",
   "title": "Regularity of the exchanges per host",
   "dataSources": {
    "primary": "ds_pattern"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "jitter = standard deviation / average interval between events. Below 0.1 means machine-driven, not human.",
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "viz_processes": {
   "type": "splunk.table",
   "title": "Processes involved (WFP)",
   "dataSources": {
    "primary": "ds_processes"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Requires Security events 5156/5157 and the wfo_wfp_index macro.",
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "hdr_raw": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Last 200 events",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_raw": {
   "type": "splunk.table",
   "title": "",
   "dataSources": {
    "primary": "ds_raw"
   },
   "options": {
    "count": 20,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "columnFormat": {
     "action": {
      "rowBackgroundColors": "> table | seriesByName(\"action\") | matchValue(actionBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "actionBgConfig": [
     {
      "match": "blocked",
      "value": "#3a1d20"
     },
     {
      "match": "allowed",
      "value": "#14301f"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  }
 },
 "dataSources": {
  "ds_traffic": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_traffic` | search (src_ip=\"$tk_peer$\" OR dest_ip=\"$tk_peer$\")"
   },
   "name": "Traffic involving this address"
  },
  "ds_wfp": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_wfp` | search (src_ip=\"$tk_peer$\" OR dest_ip=\"$tk_peer$\")"
   },
   "name": "WFP events involving this address"
  },
  "ds_kpi": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| stats count AS total, count(eval(action=\"blocked\")) AS blocked, dc(host) AS hosts, dc(dest_port) AS ports, sum(bytes) AS bytes, min(_time) AS first_seen | eval mb = round(bytes/1048576, 1), age_h = round((now()-first_seen)/3600, 1), blocked_pct = if(total>0, round(blocked*100/total,1), 0)"
   },
   "name": "KPI"
  },
  "ds_identity": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| eval peer = \"$tk_peer$\" | iplocation peer | stats values(Country) AS country, values(City) AS city, values(Region) AS region, values(src_scope) AS src_scope, values(dest_scope) AS dest_scope BY peer | eval scope = if(mvcount(mvfilter(match(mvappend(src_scope, dest_scope), \"internal\")))>0, \"internal or mixed\", \"external\") | table peer scope country region city"
   },
   "name": "Identity"
  },
  "ds_timechart": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| timechart span=5m count BY action"
   },
   "name": "Activity"
  },
  "ds_hosts": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(dest_port) AS ports, values(direction) AS direction, sum(bytes) AS bytes, min(_time) AS first_seen, max(_time) AS last_seen BY host | eval first_seen = strftime(first_seen, \"%F %T\"), last_seen = strftime(last_seen, \"%F %T\") | sort - connections | head 30"
   },
   "name": "Hosts talking to this address"
  },
  "ds_ports": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| eval service = if(isnull(dest_service), \"port \".dest_port, dest_service.\" (\".dest_port.\")\") | stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(host) AS hosts BY service, transport, direction | sort - connections | head 20"
   },
   "name": "Ports and services"
  },
  "ds_processes": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_wfp",
    "query": "| stats count AS connections, count(eval(action=\"blocked\")) AS blocked, dc(host) AS hosts, values(process_path) AS process_path BY process_name | sort - connections | head 20"
   },
   "name": "Processes (WFP)"
  },
  "ds_pattern": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| sort 0 host _time | streamstats current=f last(_time) AS previous_time BY host | eval interval = _time - previous_time | where isnotnull(interval) AND interval > 1 | stats count AS connections, avg(interval) AS avg_interval, stdev(interval) AS sd_interval BY host | eval jitter = if(avg_interval>0, round(sd_interval/avg_interval, 3), null()), avg_interval = round(avg_interval, 1) | sort + jitter | head 15"
   },
   "name": "Timing regularity"
  },
  "ds_raw": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| table _time host action direction transport src_ip src_port dest_ip dest_port dest_service bytes | sort - _time | head 200"
   },
   "name": "Raw events"
  }
 },
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@h,now"
   }
  },
  "input_peer": {
   "type": "input.text",
   "title": "IP address",
   "options": {
    "token": "tk_peer",
    "defaultValue": "*"
   }
  }
 },
 "layout": {
  "type": "grid",
  "options": {
   "width": 1440,
   "submitButton": false,
   "backgroundColor": "#0e1319"
  },
  "structure": [
   {
    "item": "hdr",
    "type": "block",
    "position": {
     "x": 0,
     "y": 0,
     "w": 1440,
     "h": 80
    }
   },
   {
    "item": "kpi_total",
    "type": "block",
    "position": {
     "x": 0,
     "y": 80,
     "w": 240,
     "h": 150
    }
   },
   {
    "item": "kpi_blocked",
    "type": "block",
    "position": {
     "x": 240,
     "y": 80,
     "w": 240,
     "h": 150
    }
   },
   {
    "item": "kpi_pct",
    "type": "block",
    "position": {
     "x": 480,
     "y": 80,
     "w": 240,
     "h": 150
    }
   },
   {
    "item": "kpi_hosts",
    "type": "block",
    "position": {
     "x": 720,
     "y": 80,
     "w": 240,
     "h": 150
    }
   },
   {
    "item": "kpi_ports",
    "type": "block",
    "position": {
     "x": 960,
     "y": 80,
     "w": 240,
     "h": 150
    }
   },
   {
    "item": "kpi_mb",
    "type": "block",
    "position": {
     "x": 1200,
     "y": 80,
     "w": 240,
     "h": 150
    }
   },
   {
    "item": "hdr_id",
    "type": "block",
    "position": {
     "x": 0,
     "y": 230,
     "w": 1440,
     "h": 40
    }
   },
   {
    "item": "viz_identity",
    "type": "block",
    "position": {
     "x": 0,
     "y": 270,
     "w": 503,
     "h": 260
    }
   },
   {
    "item": "viz_timechart",
    "type": "block",
    "position": {
     "x": 503,
     "y": 270,
     "w": 937,
     "h": 260
    }
   },
   {
    "item": "hdr_reach",
    "type": "block",
    "position": {
     "x": 0,
     "y": 530,
     "w": 1440,
     "h": 40
    }
   },
   {
    "item": "viz_hosts",
    "type": "block",
    "position": {
     "x": 0,
     "y": 570,
     "w": 864,
     "h": 420
    }
   },
   {
    "item": "viz_ports",
    "type": "block",
    "position": {
     "x": 864,
     "y": 570,
     "w": 576,
     "h": 420
    }
   },
   {
    "item": "hdr_pattern",
    "type": "block",
    "position": {
     "x": 0,
     "y": 990,
     "w": 1440,
     "h": 40
    }
   },
   {
    "item": "viz_pattern",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1030,
     "w": 720,
     "h": 360
    }
   },
   {
    "item": "viz_processes",
    "type": "block",
    "position": {
     "x": 720,
     "y": 1030,
     "w": 720,
     "h": 360
    }
   },
   {
    "item": "hdr_raw",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1390,
     "w": 1440,
     "h": 40
    }
   },
   {
    "item": "viz_raw",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1430,
     "w": 1440,
     "h": 540
    }
   }
  ],
  "globalInputs": [
   "input_time",
   "input_peer"
  ]
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     }
    }
   }
  }
 }
}
